-- Optional: the backend also creates/updates these tables automatically (spring.jpa.hibernate.ddl-auto=update).
CREATE DATABASE IF NOT EXISTS smart_study_planner; USE smart_study_planner;
CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, created_at DATETIME(6));
CREATE TABLE IF NOT EXISTS subjects (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, description VARCHAR(500), color VARCHAR(255), created_at DATETIME(6), user_id BIGINT NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks (id BIGINT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, description VARCHAR(1000), priority VARCHAR(10), status VARCHAR(20), due_date DATE, estimated_minutes INT, created_at DATETIME(6), completed_at DATETIME(6), subject_id BIGINT NULL, user_id BIGINT NOT NULL, FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE SET NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS study_sessions (id BIGINT AUTO_INCREMENT PRIMARY KEY, start_time DATETIME(6), end_time DATETIME(6), duration INT, status VARCHAR(20), task_id BIGINT NULL, subject_id BIGINT NULL, user_id BIGINT NOT NULL, FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE, FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE SET NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
